-- M2 slice 1: leads (brief §3, §4.1; D-019, D-020). A lead and a customer are one
-- record: the customers table gains a stage, a lead code, the lead status, and the lead
-- profile. Existing customers stay customers. Generated by prisma migrate diff, then the
-- checks, sequence, initial lists, permissions, and data scope added by hand below.

-- CreateEnum
CREATE TYPE "PersonStage" AS ENUM ('LEAD', 'CUSTOMER');

-- CreateEnum
CREATE TYPE "LeadStatus" AS ENUM ('NEW', 'CONSULTING', 'CONSIDERING', 'NO_RESPONSE', 'BOOKED', 'SHOWED', 'NO_SHOW', 'REFUSED', 'CONTRACTED');

-- CreateEnum
CREATE TYPE "SourceType" AS ENUM ('ORGANIC', 'PAID');

-- CreateEnum
CREATE TYPE "NationalityGroup" AS ENUM ('VIETNAM', 'FOREIGN');

-- AlterTable
ALTER TABLE "customers" ADD COLUMN     "assessment_type_note" TEXT,
ADD COLUMN     "assessment_type_option_id" UUID,
ADD COLUMN     "channel_note" TEXT,
ADD COLUMN     "channel_option_id" UUID,
ADD COLUMN     "gender" "Gender",
ADD COLUMN     "lead_code" TEXT,
ADD COLUMN     "lead_status" "LeadStatus",
ADD COLUMN     "nationality_group" "NationalityGroup",
ADD COLUMN     "need_detail" TEXT,
ADD COLUMN     "need_group_note" TEXT,
ADD COLUMN     "need_group_option_id" UUID,
ADD COLUMN     "pain_status_note" TEXT,
ADD COLUMN     "pain_status_option_id" UUID,
ADD COLUMN     "pic_user_id" UUID,
ADD COLUMN     "source_detail" TEXT,
ADD COLUMN     "source_note" TEXT,
ADD COLUMN     "source_option_id" UUID,
ADD COLUMN     "source_type" "SourceType",
ADD COLUMN     "stage" "PersonStage" NOT NULL DEFAULT 'CUSTOMER',
ALTER COLUMN "customer_code" DROP NOT NULL,
ALTER COLUMN "phone" DROP NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "customers_lead_code_key" ON "customers"("lead_code");

-- CreateIndex
CREATE INDEX "customers_stage_lead_status_idx" ON "customers"("stage", "lead_status");

-- CreateIndex
CREATE INDEX "customers_pic_user_id_idx" ON "customers"("pic_user_id");

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_channel_option_id_fkey" FOREIGN KEY ("channel_option_id") REFERENCES "options"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_source_option_id_fkey" FOREIGN KEY ("source_option_id") REFERENCES "options"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_need_group_option_id_fkey" FOREIGN KEY ("need_group_option_id") REFERENCES "options"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_pain_status_option_id_fkey" FOREIGN KEY ("pain_status_option_id") REFERENCES "options"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_assessment_type_option_id_fkey" FOREIGN KEY ("assessment_type_option_id") REFERENCES "options"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "customers" ADD CONSTRAINT "customers_pic_user_id_fkey" FOREIGN KEY ("pic_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- A lead has its lead code; a customer its customer code and a phone (D-019).
ALTER TABLE "customers" ADD CONSTRAINT "customers_stage_codes" CHECK (
    ("stage" = 'LEAD' AND "lead_code" IS NOT NULL AND "lead_status" IS NOT NULL)
    OR ("stage" = 'CUSTOMER' AND "customer_code" IS NOT NULL AND "phone" IS NOT NULL)
);

-- Lead codes never repeat (D-038).
CREATE SEQUENCE "lead_code_seq" AS BIGINT START WITH 1 INCREMENT BY 1 NO CYCLE;

