-- 09_RBAC.md: Admin, Fitness Manager, Consulting, and Receptionist (walk-ins) add and
-- work leads; the rest do not see them yet (Marketing gets lead reports in M3).
INSERT INTO "role_permissions" ("role_id", "permission")
SELECT r."id", p.permission FROM "roles" r CROSS JOIN (VALUES ('lead.view'), ('lead.create'), ('lead.manage')) AS p(permission)
WHERE r."code" IN ('ADMIN', 'FITNESS_MANAGER', 'CONSULTING', 'RECEPTIONIST');
-- Data scope "leads" (D-017): like each role's customer scope, so Consulting sees only
-- its own leads.
INSERT INTO "role_data_scopes" ("role_id", "resource", "scope")
SELECT "role_id", 'leads', "scope" FROM "role_data_scopes" WHERE "resource" = 'customers';
